import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const HEARTBEAT_MS = 1_000;
const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const IDLE_POLL_MS = 200;
const TRANSIENT_ERROR = 'transient failure';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const nowIso = () => new Date().toISOString();

// A job left 'running' by a previous worker that died is processed again from the start.
const recoverStmt = db.prepare("UPDATE jobs SET status = 'queued', not_before_ms = 0, updated_at = ? WHERE status = 'running'");
// Claim the oldest eligible queued job in one statement, starting an attempt.
const claimStmt = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ?
   WHERE rowid = (SELECT rowid FROM jobs WHERE status = 'queued' AND not_before_ms <= ? ORDER BY rowid LIMIT 1)
   RETURNING *`,
);
const progressStmt = db.prepare("UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ? AND status = 'running'");
const completeStmt = db.prepare(
  `UPDATE jobs SET status = 'completed', completed = steps, result_output = ?, error = NULL, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const failStmt = db.prepare(
  `UPDATE jobs SET status = 'failed', result_output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const requeueStmt = db.prepare(
  "UPDATE jobs SET status = 'queued', not_before_ms = ?, updated_at = ? WHERE id = ? AND status = 'running'",
);
const beatStmt = db.prepare(
  'INSERT INTO worker_heartbeat (id, beat_ms) VALUES (1, ?) ON CONFLICT (id) DO UPDATE SET beat_ms = excluded.beat_ms',
);

async function runAttempt(job: JobRow): Promise<void> {
  // Attempt numbers count from 1; attempt n fails at its first step if n <= fail_attempts.
  if (job.attempts <= job.fail_attempts) {
    if (job.attempts >= MAX_ATTEMPTS) failStmt.run(TRANSIENT_ERROR, nowIso(), job.id);
    else requeueStmt.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    // Stop between steps. The job stays 'running' and is processed again after restart.
    if (stopping) return;
    await sleep(STEP_MS);
    progressStmt.run(step, nowIso(), job.id);
  }
  completeStmt.run(job.input.toUpperCase(), nowIso(), job.id);
}

function beat(): void {
  try {
    beatStmt.run(Date.now());
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}

recoverStmt.run(nowIso());
beat();
const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);
console.log('worker started');

while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claimStmt.get(nowIso(), Date.now()) as JobRow | undefined;
  } catch (e) {
    console.error('claim failed:', e);
    await sleep(IDLE_POLL_MS);
    continue;
  }
  if (!job) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  try {
    await runAttempt(job);
  } catch (e) {
    console.error(`attempt for job ${job.id} failed:`, e);
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeatTimer);
try {
  db.prepare('DELETE FROM worker_heartbeat').run();
} catch {
  // best effort: health reports "down" once the heartbeat goes stale anyway
}
db.close();
console.log('worker stopped');
process.exit(0);

